    #[test]
    fn deepc_ok_on_single_block_comment() {
        let diags = lint_file(&*engine(), "%{\ncomment\n%}\n");
        assert!(!has_id(&diags, "DEEPC"), "got: {diags:?}");
    }

    // -- TMMSG: too many diagnostics ----------------------------------------

    #[test]
